import React from 'react';
import { render, screen, within, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Routes, Route, useLocation } from 'react-router-dom';
import Sidebar from '../src/components/Sidebar';

// ─── Test Helpers ────────────────────────────────────────────────────────────

/** Captures current location for route assertions */
const LocationDisplay = () => {
  const location = useLocation();
  return <div data-testid="location-display">{location.pathname}</div>;
};

/** Renders component within router context with optional initial route */
const renderWithRouter = (ui, { route = '/' } = {}) => {
  return render(
    <MemoryRouter initialEntries={[route]}>
      {ui}
      <LocationDisplay />
    </MemoryRouter>
  );
};

/** Mock navigation items - mirrors production data structure */
const NAV_ITEMS = [
  { label: 'Overview', path: '/overview', icon: '📊' },
  { label: 'Analytics', path: '/analytics', icon: '📈' },
  { label: 'Reports', path: '/reports', icon: '📋' },
  { label: 'Users', path: '/users', icon: '👥' },
  { label: 'Settings', path: '/settings', icon: '⚙️' },
];

// ─── Structural Integrity Tests ─────────────────────────────────────────────

describe('Sidebar Component - Structural Integrity', () => {
  test('renders without crashing', () => {
    renderWithRouter(<Sidebar />);
    expect(screen.getByRole('navigation')).toBeInTheDocument();
  });

  test('renders exactly 5 navigation items', () => {
    renderWithRouter(<Sidebar />);
    const navElement = screen.getByRole('navigation');
    const listItems = within(navElement).getAllByRole('listitem');
    expect(listItems).toHaveLength(5);
  });

  test('renders all navigation items in correct order', () => {
    renderWithRouter(<Sidebar />);
    const navElement = screen.getByRole('navigation');
    const links = within(navElement).getAllByRole('link');
    
    const expectedOrder = ['Overview', 'Analytics', 'Reports', 'Users', 'Settings'];
    const actualOrder = links.map(link => link.textContent.trim());
    
    expect(actualOrder).toEqual(expectedOrder);
  });

  test('renders navigation items with correct href attributes', () => {
    renderWithRouter(<Sidebar />);
    const navElement = screen.getByRole('navigation');
    const links = within(navElement).getAllByRole('link');
    
    const expectedPaths = ['/overview', '/analytics', '/reports', '/users', '/settings'];
    const actualPaths = links.map(link => link.getAttribute('href'));
    
    expect(actualPaths).toEqual(expectedPaths);
  });

  test('renders icons for each navigation item', () => {
    renderWithRouter(<Sidebar />);
    const navElement = screen.getByRole('navigation');
    const listItems = within(navElement).getAllByRole('listitem');
    
    listItems.forEach((item, index) => {
      expect(within(item).getByText(NAV_ITEMS[index].icon)).toBeInTheDocument();
    });
  });

  test('applies correct CSS classes to navigation container', () => {
    renderWithRouter(<Sidebar />);
    const navElement = screen.getByRole('navigation');
    expect(navElement).toHaveClass('sidebar');
    expect(navElement).toHaveClass('nav');
  });
});

// ─── Navigation Behavior Tests ──────────────────────────────────────────────

describe('Sidebar Component - Navigation Behavior', () => {
  test('navigates to correct route when clicking a nav item', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    const analyticsLink = screen.getByRole('link', { name: /analytics/i });
    await user.click(analyticsLink);
    
    expect(screen.getByTestId('location-display')).toHaveTextContent('/analytics');
  });

  test('navigates to root route when clicking Overview', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />, { route: '/reports' });
    
    const overviewLink = screen.getByRole('link', { name: /overview/i });
    await user.click(overviewLink);
    
    expect(screen.getByTestId('location-display')).toHaveTextContent('/overview');
  });

  test('updates location for each navigation item sequentially', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    for (const item of NAV_ITEMS) {
      const link = screen.getByRole('link', { name: new RegExp(item.label, 'i') });
      await user.click(link);
      expect(screen.getByTestId('location-display')).toHaveTextContent(item.path);
    }
  });

  test('handles rapid consecutive clicks without errors', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    const links = screen.getAllByRole('link');
    for (const link of links) {
      await user.click(link);
    }
    
    // Should not throw and should end on last route
    expect(screen.getByTestId('location-display')).toHaveTextContent('/settings');
  });

  test('preserves query parameters during navigation', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />, { route: '/overview?tab=details' });
    
    const reportsLink = screen.getByRole('link', { name: /reports/i });
    await user.click(reportsLink);
    
    expect(screen.getByTestId('location-display')).toHaveTextContent('/reports');
  });
});

// ─── Active State Management Tests ──────────────────────────────────────────

describe('Sidebar Component - Active State Management', () => {
  test('highlights the active navigation item based on current route', () => {
    renderWithRouter(<Sidebar />, { route: '/analytics' });
    
    const analyticsLink = screen.getByRole('link', { name: /analytics/i });
    expect(analyticsLink).toHaveClass('active');
    expect(analyticsLink).toHaveAttribute('aria-current', 'page');
  });

  test('does not highlight inactive navigation items', () => {
    renderWithRouter(<Sidebar />, { route: '/analytics' });
    
    const overviewLink = screen.getByRole('link', { name: /overview/i });
    expect(overviewLink).not.toHaveClass('active');
    expect(overviewLink).not.toHaveAttribute('aria-current');
  });

  test('updates active state when route changes', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />, { route: '/overview' });
    
    const reportsLink = screen.getByRole('link', { name: /reports/i });
    await user.click(reportsLink);
    
    expect(reportsLink).toHaveClass('active');
    expect(reportsLink).toHaveAttribute('aria-current', 'page');
    
    const overviewLink = screen.getByRole('link', { name: /overview/i });
    expect(overviewLink).not.toHaveClass('active');
  });

  test('handles nested route paths for active state', () => {
    renderWithRouter(<Sidebar />, { route: '/users/123/details' });
    
    const usersLink = screen.getByRole('link', { name: /users/i });
    expect(usersLink).toHaveClass('active');
  });
});

// ─── Accessibility Tests ────────────────────────────────────────────────────

describe('Sidebar Component - Accessibility', () => {
  test('has correct ARIA role for navigation', () => {
    renderWithRouter(<Sidebar />);
    expect(screen.getByRole('navigation')).toBeInTheDocument();
  });

  test('all navigation links are keyboard accessible', () => {
    renderWithRouter(<Sidebar />);
    const links = screen.getAllByRole('link');
    
    links.forEach(link => {
      expect(link).toHaveAttribute('href');
      expect(link).not.toHaveAttribute('tabindex', '-1');
    });
  });

  test('supports keyboard navigation with Tab key', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    const firstLink = screen.getAllByRole('link')[0];
    firstLink.focus();
    
    await user.tab();
    expect(screen.getAllByRole('link')[1]).toHaveFocus();
    
    await user.tab();
    expect(screen.getAllByRole('link')[2]).toHaveFocus();
  });

  test('supports Enter key to activate navigation', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    const analyticsLink = screen.getByRole('link', { name: /analytics/i });
    analyticsLink.focus();
    await user.keyboard('{Enter}');
    
    expect(screen.getByTestId('location-display')).toHaveTextContent('/analytics');
  });

  test('provides accessible labels for icon-only navigation', () => {
    renderWithRouter(<Sidebar />);
    const links = screen.getAllByRole('link');
    
    links.forEach(link => {
      expect(link).toHaveAccessibleName();
      expect(link.getAttribute('aria-label') || link.textContent.trim()).toBeTruthy();
    });
  });

  test('maintains focus visibility styles', () => {
    renderWithRouter(<Sidebar />);
    const links = screen.getAllByRole('link');
    
    links.forEach(link => {
      expect(link).toHaveClass('focusable');
      expect(link).toHaveStyle({ outline: 'none' });
    });
  });
});

// ─── Edge Case Tests ────────────────────────────────────────────────────────

describe('Sidebar Component - Edge Cases', () => {
  test('handles empty navigation items gracefully', () => {
    // Mock Sidebar to accept empty items prop
    renderWithRouter(<Sidebar items={[]} />);
    
    const navElement = screen.getByRole('navigation');
    expect(within(navElement).queryAllByRole('listitem')).toHaveLength(0);
    expect(within(navElement).queryAllByRole('link')).toHaveLength(0);
  });

  test('handles invalid route without crashing', () => {
    renderWithRouter(<Sidebar />, { route: '/nonexistent-route' });
    
    expect(screen.getByRole('navigation')).toBeInTheDocument();
    // No active item should be highlighted
    const activeLinks = screen.getAllByRole('link').filter(link => 
      link.classList.contains('active')
    );
    expect(activeLinks).toHaveLength(0);
  });

  test('handles undefined route gracefully', () => {
    renderWithRouter(<Sidebar />, { route: undefined });
    
    expect(screen.getByRole('navigation')).toBeInTheDocument();
    expect(screen.getByTestId('location-display')).toHaveTextContent('/');
  });

  test('handles special characters in navigation labels', () => {
    const specialItems = [
      { label: 'Data & Reports', path: '/data-reports', icon: '📊' },
      { label: 'User\'s Profile', path: '/user-profile', icon: '👤' },
    ];
    
    renderWithRouter(<Sidebar items={specialItems} />);
    
    expect(screen.getByRole('link', { name: /data & reports/i })).toBeInTheDocument();
    expect(screen.getByRole('link', { name: /user's profile/i })).toBeInTheDocument();
  });

  test('handles long navigation labels without overflow', () => {
    const longLabelItems = [
      { label: 'Very Long Navigation Label That Should Not Overflow', path: '/long', icon: '📄' },
    ];
    
    renderWithRouter(<Sidebar items={longLabelItems} />);
    
    const link = screen.getByRole('link');
    expect(link).toHaveClass('truncate');
    expect(link).toHaveStyle({ overflow: 'hidden' });
  });

  test('handles duplicate navigation paths', () => {
    const duplicateItems = [
      { label: 'Dashboard', path: '/dashboard', icon: '📊' },
      { label: 'Home', path: '/dashboard', icon: '🏠' },
    ];
    
    renderWithRouter(<Sidebar items={duplicateItems} />);
    
    const links = screen.getAllByRole('link');
    expect(links).toHaveLength(2);
    // Both should navigate to same route
    expect(links[0].getAttribute('href')).toBe('/dashboard');
    expect(links[1].getAttribute('href')).toBe('/dashboard');
  });
});

// ─── Integration Tests ──────────────────────────────────────────────────────

describe('Sidebar Component - Integration', () => {
  test('integrates with route definitions correctly', async () => {
    const user = userEvent.setup();
    
    const TestComponent = () => <div>Test Page</div>;
    
    render(
      <MemoryRouter initialEntries={['/']}>
        <Sidebar />
        <Routes>
          <Route path="/overview" element={<TestComponent />} />
          <Route path="/analytics" element={<TestComponent />} />
          <Route path="/reports" element={<TestComponent />} />
          <Route path="/users" element={<TestComponent />} />
          <Route path="/settings" element={<TestComponent />} />
        </Routes>
        <LocationDisplay />
      </MemoryRouter>
    );
    
    // Click each nav item and verify route renders
    for (const item of NAV_ITEMS) {
      const link = screen.getByRole('link', { name: new RegExp(item.label, 'i') });
      await user.click(link);
      
      expect(screen.getByTestId('location-display')).toHaveTextContent(item.path);
      expect(screen.getByText('Test Page')).toBeInTheDocument();
    }
  });

  test('maintains sidebar visibility across route changes', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    const navElement = screen.getByRole('navigation');
    
    for (const item of NAV_ITEMS) {
      const link = screen.getByRole('link', { name: new RegExp(item.label, 'i') });
      await user.click(link);
      
      // Sidebar should persist
      expect(navElement).toBeInTheDocument();
      expect(screen.getByRole('navigation')).toBe(navElement);
    }
  });

  test('handles browser back/forward navigation', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />, { route: '/overview' });
    
    // Navigate forward
    const analyticsLink = screen.getByRole('link', { name: /analytics/i });
    await user.click(analyticsLink);
    expect(screen.getByTestId('location-display')).toHaveTextContent('/analytics');
    
    // Navigate back
    fireEvent.popState(window);
    await waitFor(() => {
      expect(screen.getByTestId('location-display')).toHaveTextContent('/overview');
    });
  });
});

// ─── Performance & Robustness Tests ─────────────────────────────────────────

describe('Sidebar Component - Performance & Robustness', () => {
  test('renders efficiently with large navigation sets', () => {
    const largeItems = Array.from({ length: 100 }, (_, i) => ({
      label: `Item ${i}`,
      path: `/item-${i}`,
      icon: '📄',
    }));
    
    const startTime = performance.now();
    renderWithRouter(<Sidebar items={largeItems} />);
    const endTime = performance.now();
    
    expect(screen.getAllByRole('link')).toHaveLength(100);
    expect(endTime - startTime).toBeLessThan(1000); // Should render in under 1s
  });

  test('handles rapid route changes without memory leaks', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    // Rapidly click through all items multiple times
    for (let cycle = 0; cycle < 3; cycle++) {
      for (const item of NAV_ITEMS) {
        const link = screen.getByRole('link', { name: new RegExp(item.label, 'i') });
        await user.click(link);
      }
    }
    
    // Verify final state is correct
    expect(screen.getByTestId('location-display')).toHaveTextContent('/settings');
    expect(screen.getByRole('navigation')).toBeInTheDocument();
  });

  test('maintains state integrity during concurrent interactions', async () => {
    const user = userEvent.setup();
    renderWithRouter(<Sidebar />);
    
    // Simulate concurrent clicks
    const clickPromises = NAV_ITEMS.map(item => 
      user.click(screen.getByRole('link', { name: new RegExp(item.label, 'i') }))
    );
    
    await Promise.all(clickPromises);
    
    // Should not crash and should have valid state
    expect(screen.getByRole('navigation')).toBeInTheDocument();
    expect(screen.getByTestId('location-display')).toBeTruthy();
  });
});